ms:center;gap:11px;font:800 13px var(--body);letter-spacing:.09em}.brand-mark small{display:block;margin-top:3px;font:8px var(--mono);letter-spacing:.12em;color:#b1b8aa}.brand-symbol{font:800 25px var(--display);color:var(--acid);border-left:2px solid var(--acid);padding-left:8px;line-height:1}.brand-symbol span{font-size:12px;vertical-align:top}.round-panel{text-align:center}.hud-label{display:block;color:#aab3a4;font:8px var(--mono);letter-spacing:.17em}.round-panel strong{display:block;margin:4px 0 7px;font:700 19px var(--display);letter-spacing:.11em}.round-panel strong b{color:var(--acid)}.wave-progress{height:2px;background:rgba(232,237,221,.2);width:100%;overflow:hidden}.wave-progress span{display:block;width:0;height:100%;background:var(--acid);transition:width .3s}.round-panel small,.cash-panel small{display:block;margin-top:5px;color:#aab3a4;font:8px var(--mono);letter-spacing:.1em}.cash-panel{text-align:right}.cash-panel strong{display:block;margin-top:3px;font:700 27px var(--display);letter-spacing:.04em}.cash-panel strong i{font-style:normal;color:var(--acid);font-size:17px;margin-right:3px}.cash-panel small{margin-top:0}.threat-label{position:absolute;top:20%;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px;color:#d4dacb;font:9px var(--mono);letter-spacing:.14em}.threat-label .signal-dot{width:5px;height:5px;background:var(--orange);box-shadow:0 0 9px var(--orange);margin-right:5px}.threat-label b{color:#fff;font-weight:500}.threat-line{width:52px;height:1px;background:linear-gradient(90deg,transparent,rgba(221,231,207,.5))}.threat-line:last-child{transform:rotate(180deg)}.crosshair{position:absolute;left:50%;top:50%;width:26px;height:26px;transform:translate(-50%,-50%);opacity:.8}.crosshair i{position:absolute;display:block;width:2px;height:6px;background:#dce8d0;left:12px}.crosshair i:nth-child(1){top:0}.crosshair i:nth-child(2){bottom:0}.crosshair i:nth-child(3),.crosshair i:nth-child(4){width:6px;height:2px;top:12px;left