on:absolute;left:50%;top:31%;transform:translate(-50%,-10px);padding:10px 17px;border-left:2px solid var(--acid);background:rgba(13,20,15,.8);font:10px var(--mono);letter-spacing:.12em;opacity:0;transition:.3s}.toast.show{opacity:1;transform:translate(-50%,0)}.damage-flash{position:absolute;inset:0;background:rgba(211,48,38,.22);opacity:0;transition:opacity .12s}.damage-flash.active{opacity:1}.modal-screen{align-items:center;justify-content:center;background:rgba(8,13,10,.78);backdrop-filter:blur(8px)}.modal-card{width:min(440px,90vw);padding:43px 48px;background:linear-gradient(135deg,rgba(30,39,30,.97),rgba(17,24,19,.97));border:1px solid rgba(213,238,112,.22);box-shadow:0 25px 100px #050806}.modal-card h2,.shop-header h2{margin:0;font:900 71px/.78 var(--display);letter-spacing:-.015em}.modal-card h2 span,.shop-header h2 span{color:var(--acid)}.modal-card>p:not(.eyebrow){color:#b4bdb0;font-size:12px;line-height:1.6;margin:22px 0}.modal-foot{margin-top:26px;color:#849083;font:8px var(--mono);letter-spacing:.13em}.modal-foot i{color:var(--acid);font-style:normal;padding:0 8px}.pause-card .primary-button,.gameover-card .primary-button{margin-top:25px}.gameover-card .eyebrow{color:var(--orange)}.gameover-card h2 span{color:var(--orange)}.shop-wrap{width:min(930px,91vw);padding:30px 42px 25px;background:linear-gradient(135deg,rgba(28,37,29,.98),rgba(15,21,17,.98));border:1px solid rgba(213,238,112,.2);box-shadow:0 25px 110px #050806}.shop-header{display:flex;justify-content:space-between;align-items:end}.shop-header .eyebrow{margin-bottom:13px}.shop-header h2{font-size:59px}.shop-round{text-align:right;padding-bottom:5px}.shop-round span,.shop-round small{display:block;color:#aab3a4;font:8px var(--mono);letter-spacing:.14em}.shop-round b{display:block;margin:5px 0;color:#e8eadc;font:700 18px var(--display);letter-spacing:.1em}.shop-round b i{font-style:normal;color:var(--acid)}.shop-divider{display:flex;align-items:center;gap:11px;margin:23px 0 14px;color:#d8ddce;font:9px var(--mono);letter-spacing:.14em}.shop-divider span{height:1px;flex:1;background:rgba(220,230,207,.16)}.shop-divider strong{font:12px var(--mono);color:var(--acid);margin-left:8px}.shop-divider strong i{font-style:normal}.upgrade-list{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.upgrade-card{min-height:133px;position:relative;padding:16px 15px 13px;background:rgba(231,239,218,.035);border:1px solid rgba(231,239,218,.12);transition:.2s}.upgrade-card:hover{border-color:rgba(213,238,112,.6);background:rgba(213,238,112,.06)}.upgrade-card.purchased{opacity:.43}.upgrade-icon{position:absolute;right:14px;top:11px;color:var(--acid);font:23px var(--display)}.upgrade-card h3{margin:0 0 6px;font:700 17px var(--display);letter-spacing:.04em}.upgrade-card p{max-width:200px;margin:0;color:#aab3a4;font-size:9px;line-height:1.45}.upgrade-card button{position:absolute;right:12px;bottom:11px;padding:6px 9px;background:transparent;border:1px solid rgba(213,238,112,.55);color:var(--acid);cursor:pointer;font:9px var(--mono);letter-spacing:.08em}.upgrade-card button:hover:not(:disabled){background:var(--acid);color:var(--ink)}.upgrade-card button:disabled{opacity:.4;cursor:not-allowed}.card-tag{position:absolute;bottom:14px;left:15px;color:#889486;font:8px var(--mono);letter-spacing:.08em}.shop-footer{display:flex;justify-content:space-between;align-items:center;margin-top:18px}.shop-footer>div{color:#9ba697;font:8px var(--mono);letter-spacing:.1em}.shop-footer .signal-dot{width:5px;height:5px;margin-right:7px}.shop-footer .primary-button{height:43px;min-width:220px;font-size:10px}.lock-prompt{position:absolute;z-index:5;left:50%;top:58%;transform:translate(-50%,-50%);padding:12px 18px;background:rgba(9,15,11,.85);border:1px solid rgba(213,238,112,.55);color:var(--acid);font:10px var(--mono);letter-spacing:.13em}.lock-prompt.hidden{display:none}
